#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/button_base/button/button_values/button_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// Button's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/button.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Standard, flat, accent or command button.
template <typename Declaring>
struct ButtonVisualStyleChoiceCapability {
    PropertyCell<ButtonVisualStyle, ButtonVisualStyleChoiceCapability<Declaring>> visual_style{ButtonVisualStyle::standard};

    static void assign(ButtonVisualStyleChoiceCapability& capability, ButtonVisualStyle incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.visual_style), incoming);
        if (!capability.visual_style.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.visual_style));
    }
};

// Border width in logical pixels of a flat button; finite and nonnegative (std::invalid_argument).
template <typename Declaring>
struct ButtonFlatBorderWidthCapability {
    PropertyCell<double, ButtonFlatBorderWidthCapability<Declaring>> flat_border_width{1.0};

    static void assign(ButtonFlatBorderWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.flat_border_width), incoming);
        if (!capability.flat_border_width.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.flat_border_width));
    }
};

// ButtonVisualStyle as a property value; defined beside Button's table.
template <>
struct PropertyValueTraits<ButtonVisualStyle> {
    static PropertyType type();
    static BindingValue to_binding(ButtonVisualStyle value);
    static ButtonVisualStyle from_binding(const BindingValue& value);
};

// Every Button capability, in the order the declaring class takes them.
template <typename Declaring>
struct ButtonCapabilities : public ButtonVisualStyleChoiceCapability<Declaring>,
                            public ButtonFlatBorderWidthCapability<Declaring> {};

} // namespace gui_forms
